from fastapi import APIRouter

router = APIRouter()


@router.get("/")
async def get_alerts():
    """Get recent alerts/trade setups generated by the system."""
    return {"alerts": []}


@router.post("/trigger-scan")
async def trigger_scan():
    """Manually trigger a market scan."""
    from app.agents.orchestrator import run_market_scan
    result = await run_market_scan()
    return {"status": "scan_complete", "result": result}


@router.post("/test-telegram")
async def test_telegram():
    """Send a test message to Telegram to verify setup."""
    from app.services.telegram_service import send_telegram_alert
    message = (
        "🤖 *AI Market Copilot - Test Alert*\n\n"
        "✅ Telegram integration is working!\n\n"
        "You will receive:\n"
        "• Market scan reports every 30 min during market hours\n"
        "• Momentum stock alerts\n"
        "• Portfolio risk warnings\n\n"
        "🚀 System is online and ready."
    )
    success = await send_telegram_alert(message)
    return {"status": "sent" if success else "failed", "message": "Check your Telegram!"}

